-- Preserve all claims and retirement-aware constraints; change only literal-zero precision interpretation.
DROP TRIGGER atlas_attribute_contract;
--> statement-breakpoint
CREATE TRIGGER atlas_attribute_contract BEFORE INSERT ON atlas_attribute_records BEGIN
 SELECT RAISE(ABORT,'Attribute requires a location territory') WHERE NOT EXISTS(SELECT 1 FROM atlas_entities e WHERE e.id=NEW.location_id AND e.kind='location');
 SELECT RAISE(ABORT,'Category kind mismatch') WHERE NEW.category_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM atlas_categories c WHERE c.id=NEW.category_id AND c.kind=NEW.attribute);
 SELECT RAISE(ABORT,'Overlapping attribute evidence') WHERE NOT EXISTS(SELECT 1 FROM atlas_evidence_retirements retired WHERE retired.collection='records' AND retired.target_id=NEW.id) AND EXISTS(SELECT 1 FROM atlas_attribute_records r WHERE r.id!=NEW.id AND NOT EXISTS(SELECT 1 FROM atlas_evidence_retirements retired WHERE retired.collection='records' AND retired.target_id=r.id) AND r.location_id=NEW.location_id AND r.attribute=NEW.attribute AND r.method=NEW.method AND r.is_example=NEW.is_example AND r.valid_from<NEW.valid_to AND r.valid_to>NEW.valid_from);
 SELECT RAISE(ABORT,'Attribute exceeds location lifetime') WHERE EXISTS(SELECT 1 FROM atlas_entities e WHERE e.id=NEW.location_id AND ((e.valid_from IS NOT NULL AND NEW.valid_from<e.valid_from) OR (e.valid_to IS NOT NULL AND NEW.valid_to>e.valid_to)));
 SELECT RAISE(ABORT,'Uninhabited / unsettled conflicts with settlement attributes') WHERE NEW.method='direct' AND NOT EXISTS(SELECT 1 FROM atlas_evidence_retirements retired WHERE retired.collection='records' AND retired.target_id=NEW.id) AND EXISTS(SELECT 1 FROM atlas_attribute_records r WHERE r.id!=NEW.id AND NOT EXISTS(SELECT 1 FROM atlas_evidence_retirements retired WHERE retired.collection='records' AND retired.target_id=r.id) AND r.location_id=NEW.location_id AND r.method='direct' AND r.is_example=NEW.is_example AND r.valid_from<NEW.valid_to AND r.valid_to>NEW.valid_from AND ((((NEW.attribute='habitation' AND json_extract(NEW.value,'$')='uninhabited') OR (NEW.attribute='rank' AND json_extract(NEW.value,'$')='unsettled') OR (NEW.attribute='population' AND NEW.method='direct' AND NEW.status='sourced' AND json_extract(NEW.value,'$')=0 AND coalesce(json_extract(NEW.metadata,'$.estimate'),0)=0 AND coalesce(json_extract(NEW.metadata,'$.estimated'),0)=0 AND coalesce(json_extract(NEW.metadata,'$.is_estimate'),0)=0 AND coalesce(json_extract(NEW.metadata,'$.modeled'),0)=0 AND coalesce(json_extract(NEW.metadata,'$.modelled'),0)=0 AND coalesce(json_extract(NEW.metadata,'$.rounded'),0)=0 AND coalesce(json_extract(NEW.metadata,'$.legacy_snapshot'),0)=0 AND coalesce(json_extract(NEW.metadata,'$.legacy_attributes'),0)=0 AND (json_type(NEW.metadata,'$.rounding') IS NULL OR json_type(NEW.metadata,'$.rounding')='null') AND (json_type(NEW.metadata,'$.model') IS NULL OR json_type(NEW.metadata,'$.model')='null') AND lower(coalesce(json_extract(NEW.metadata,'$.precision'),'')) NOT LIKE '%round%' AND lower(coalesce(json_extract(NEW.metadata,'$.precision'),'')) NOT LIKE '%model%' AND lower(coalesce(json_extract(NEW.metadata,'$.precision'),'')) NOT LIKE '%estimate%' AND lower(coalesce(json_extract(NEW.metadata,'$.precision'),'')) NOT LIKE '%approx%')) AND ((r.attribute='habitation' AND json_extract(r.value,'$')='inhabited') OR (r.attribute='rank' AND json_extract(r.value,'$') IN ('rural settlement','town','city','metropolis')) OR (r.attribute='population' AND json_extract(r.value,'$')>0))) OR (((NEW.attribute='habitation' AND json_extract(NEW.value,'$')='inhabited') OR (NEW.attribute='rank' AND json_extract(NEW.value,'$') IN ('rural settlement','town','city','metropolis')) OR (NEW.attribute='population' AND json_extract(NEW.value,'$')>0)) AND ((r.attribute='habitation' AND json_extract(r.value,'$')='uninhabited') OR (r.attribute='rank' AND json_extract(r.value,'$')='unsettled') OR (r.attribute='population' AND r.method='direct' AND r.status='sourced' AND json_extract(r.value,'$')=0 AND coalesce(json_extract(r.metadata,'$.estimate'),0)=0 AND coalesce(json_extract(r.metadata,'$.estimated'),0)=0 AND coalesce(json_extract(r.metadata,'$.is_estimate'),0)=0 AND coalesce(json_extract(r.metadata,'$.modeled'),0)=0 AND coalesce(json_extract(r.metadata,'$.modelled'),0)=0 AND coalesce(json_extract(r.metadata,'$.rounded'),0)=0 AND coalesce(json_extract(r.metadata,'$.legacy_snapshot'),0)=0 AND coalesce(json_extract(r.metadata,'$.legacy_attributes'),0)=0 AND (json_type(r.metadata,'$.rounding') IS NULL OR json_type(r.metadata,'$.rounding')='null') AND (json_type(r.metadata,'$.model') IS NULL OR json_type(r.metadata,'$.model')='null') AND lower(coalesce(json_extract(r.metadata,'$.precision'),'')) NOT LIKE '%round%' AND lower(coalesce(json_extract(r.metadata,'$.precision'),'')) NOT LIKE '%model%' AND lower(coalesce(json_extract(r.metadata,'$.precision'),'')) NOT LIKE '%estimate%' AND lower(coalesce(json_extract(r.metadata,'$.precision'),'')) NOT LIKE '%approx%')))));
END;
